	"encoding/json"
	"fmt"
	"log"
	"sync"
	"time"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// State for each node
type NodeState struct {
	values      map[int64]int // broadcast ID -> value (we just need to store values per node, but actually each node needs ALL values for read)
	syncedTo    map[int64]map[string]bool // sync tracking - which nodes know about which values
}

// Actually, let's simplify: we just need to track what values exist and forward broadcasts
// The key insight is that once a value reaches some nodes, it should be forwarded to others

type Node struct {
	maelstrom.Node
	self string // our own node ID
}

func (n *Node) Handle(msg *maelstrom.Message) error {
	switch msg.Type {
	case "topology":
		return n.handleToplogy(msg)
	case "broadcast":
		return n.handleBroadcast(msg)
	case "read":
		return n.handleRead(msg)
	default:
		return nil
	}
}

func (n *Node) handleToplogy(msg *maelstrom.Message) error {
	var topologyMsg struct {
		Topology map[string][]string `json:"topology"`
	}
	if err := json.Unmarshal(msg.Body, &topologyMsg); err != nil {
		return err
	}

	// Convert topology to a usable form
	nodeNeighbors := make(map[string]map[string]bool)
	for nodeID, neighbors := range topologyMsg.Topology {
		nodeNeighbors[nodeID] = make(map[string]bool)
		for _, n := range neighbors {
			nodeNeighbors[nodeID][n] = true
		}
	}

	// Store this topology info
	n.nodeNeighbors = nodeNeighbors

	return maelstrom.Reply("topology_ok", nil, msg)
}

func (n *Node) handleBroadcast(msg *maelstrom.Message) error {
	var broadcastMsg struct {
		Message   int64  `json:"message"`
		Broadcast bool   `json:"broadcast"`
	}
	if err := json.Unmarshal(msg.Body, &broadcastMsg); err != nil {
		return err
	}

	value := broadcastMsg.Message

	// Store the value
	n.values = append(n.values, value)

	// Broadcast to all known neighbors
	for neighborID := range n.nodeNeighbors[n.self] {
		body, _ := json.Marshal(map[string]interface{}{
			"type":        "forward",
			"value":       value,
			"from_node_id": n.self,
		})
		n.Send(neighborID, body)
	}

	return maelstrom.Reply("broadcast_ok", nil, msg)
}

func (n *Node) handleRead(msg *maelstrom.Message) error {
	body, _ := json.Marshal(map[string]interface{}{
		"type":     "read_ok",
		"messages": n.values,
	})
	return maelstrom.Reply("read_ok", body, msg)
}

