package main

import (
	"encoding/json"
	"log"
	"sync"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// State maintained per node
type Node struct {
	maelstrom.Node
	self        string                 // our own ID
	nodeToPeer  map[string]setNode     // for each remote peer, what values they have told us about
	setNode     setIDSet               // set of (nodeID, value) pairs we know exist
	values      setInt64               // all values we have ever seen/broadcast
}

// Efficient tracking using a simple map
type Node struct {
	maelstrom.Node
	self             string            // our node ID
	allNodes         map[string]bool   // all known node IDs
	nodeSet          map[string]struct{} // quick set for node membership
	values           map[int64]bool     // values we've seen (for read)
	forwarding       map[string][]int64 // peer -> list of values to forward (deduped per peer)
	valuesSent       map[string]map[int64]int // peer -> value -> send count (to avoid re-sending same value)
	mu               sync.Mutex
}

func (n *Node) init(msg *maelstrom.Message) error {
	if msg.Type == "init" {
		n.Node.Init()
		log.Printf("init: self=%s", n.Self())
	}
	return nil
}

func (n *Node) handleToplogy(msg *maelstrom.Message) error {
	var topologyMsg struct {
		Topology map[string][]string `json:"topology"`
	}
	if err := json.Unmarshal(msg.Body, &topologyMsg); err != nil {
		return err
	}

	// Parse topology and store our neighbors
	n.nodeNeighbors = make(map[string]map[string]bool)
	for nodeID, neighborList := range topologyMsg.Topology {
		nodeNeighbors[nodeID] = make(map[string]bool)
		for _, neighbor := range neighborList {
			nodeNeighbors[nodeID][neighbor] = true
		}
	}

	// Keep track of all known nodes (from any topology message we might see)
	allNodes := make(map[string]bool)
	for nodeID := range topologyMsg.Topology {
		allNodes[nodeID] = true
	}

	// Store topology info
	n.nodeNeighbors = topologyMsg.Topology
	n.allNodes = allNodes

	return maelstrom.Reply("topology_ok", nil, msg)
}

func (n *Node) handleBroadcast(msg *maelstrom.Message) error {
	var broadcastMsg struct {
		Message   int64  `json:"message"`
		Broadcast bool   `json:"broadcast"`
	}
	if err := json.Unmarshal(msg.Body, &broadcastMsg); err != nil {
		return err
	}

	value := broadcastMsg.Message

	// Record the value we know about
	n.mu.Lock()
	n.values[value] = true

	// We want to forward this to all other nodes. 
	// But instead of blindly using topology neighbors, let's try to reach everyone.
	// Since topology might not be complete (it says n1 -> [n2,n3] but maybe n4 exists too),
	// we should check against our known nodes.

	// Build a list of all node IDs we know about
	allNodeIDs := make([]string, 0, len(n.allNodes))
	for id := range n.allNodes {
		if id != n.Self() {
			allNodeIDs = append(allNodeIDs, id)
		}
	}

	// Forward to all other known nodes
	for targetID := range allNodeIDs {
		n.forwarding[targetID] = append(n.forwarding[targetID], value)
	}
	n.mu.Unlock()

	return maelstrom.Reply("broadcast_ok", nil, msg)
}

func (n *Node) handleRead(msg *maelstrom.Message) error {
	n.mu.Lock()
	values := make([]int64, 0, len(n.values))
	for v := range n.values {
		values = append(values, v)
	}
	n.mu.Unlock()

	body, _ := json.Marshal(map[string]interface{}{
		"type":     "read_ok",
		"messages": values,
	})
	return maelstrom.Reply("read_ok", body, msg)
}

func main() {
	n := &Node{
		Node:             maelstrom.NewNode(),
		nodeNeighbors:    make(map[string]map[string]bool),
		values:           make(map[int64]bool),
		forwarding:       make(map[string][]int64),
		valuesSent:       make(map[string]map[int64]int),
		allNodes:         make(map[string]bool),
	}

