	n.Node.Handle(func(msg *maelstrom.Message) {
		if msg.Type == "init" {
			log.Printf("initialized, self=%s", n.Self())
		}
	})

	// Handle topology
	n.Node.Handle(func(msg *maelstrom.Message) {
		if msg.Type == "topology" {
			if err := n.handleToplogy(msg); err != nil {
				log.Printf("error handling topology: %v", err)
			}
		}
	})

	// Handle broadcast
	n.Node.Handle(func(msg *maelstrom.Message) {
		if msg.Type == "broadcast" {
			if err := n.handleBroadcast(msg); err != nil {
				log.Printf("error handling broadcast: %v", err)
			}
		}
	})

	// Handle read
	n.Node.Handle(func(msg *maelstrom.Message) {
		if msg.Type == "read" {
			if err := n.handleRead(msg); err != nil {
				log.Printf("error handling read: %v", err)
			}
		}
	})

	n.Run()
