		return err
	}

	value := broadcastMsg.Message

	// Store the value we know about
	n.mu.Lock()
	n.values[value] = true

	// Get our neighbors (excluding self)
	neighbors := make([]string, 0)
	for id := range n.nodeNeighbors[n.self] {
		if id != n.Self() {
			neighbors = append(neighbors, id)
		}
	}
	n.mu.Unlock()

	// Forward to each neighbor with the value
	sendBody := func(target string) ([]byte, error) {
		payload := map[string]interface{}{
			"type":        "forward",
			"value":       value,
			"from_node_id": n.Self(),
			"to_node_id":   target,
		}
		return json.Marshal(payload)
	}

